//! Every act: how long it is, and which bosses it reveals in what order.
//!
//! The smallest domain, and the one the others were already pointing at.
//! Monsters, encounters and events each say which act they belong to, and until
//! now nothing said what an act is. So `Act` was generated by the *monsters*
//! domain, from the act ids that happened to appear in its dump. It lives here
//! now, and those three import it.
//!
//! The xtask README says why `index` is not a run position, and what this
//! domain deliberately leaves to the event and encounter dumps.

use std::fmt::Write as _;
use std::path::Path;

use super::DumpError;
use super::{Build, DERIVES, Dump, banner, camel, repr};
use crate::error::{self, FileError};

#[derive(Debug, thiserror::Error)]
pub enum Error {
    #[error(transparent)]
    Dump(#[from] DumpError),
    #[error(transparent)]
    File(#[from] FileError),
    #[error(transparent)]
    Set(#[from] super::sets::Error),
    #[error(transparent)]
    Bridge(#[from] super::bridge::Error),
    #[error("{act}: boss {order} arrived out of order, after {after}")]
    BossOrder {
        act: String,
        order: usize,
        after: usize,
    },
    #[error("an act reveals {0} bosses, past the {BOSS_CAP} a Bosses can hold")]
    TooManyBosses(usize),
}

pub fn generate(root: &Path) -> Result<Build, Error> {
    let dump = Dump::read("acts.txt")?;
    let build = dump.build.clone();

    let acts: Vec<&Vec<String>> = dump.of("act").collect();
    if acts.is_empty() {
        return Err(DumpError::Empty("acts").into());
    }
    for row in &acts {
        if row.len() != 6 {
            return Err(DumpError::Columns {
                id: row[1].clone(),
                got: row.len() - 1,
                want: 5,
            }
            .into());
        }
    }

    // The bosses an act reveals, in order. Kept as a list rather than a set,
    // because the order is which boss a first run ends against.
    let mut bosses: Vec<(String, Vec<String>)> = Vec::new();
    for row in dump.of("boss") {
        let order: usize = DumpError::number(format_args!("{}: boss order", row[1]), &row[2])?;

        let entry = match bosses.iter_mut().find(|(id, _)| *id == row[1]) {
            Some(entry) => entry,
            None => {
                bosses.push((row[1].clone(), Vec::new()));
                bosses.last_mut().expect("just pushed")
            }
        };

        if entry.1.len() != order {
            return Err(Error::BossOrder {
                act: row[1].clone(),
                order,
                after: entry.1.len(),
            });
        }
        entry.1.push(row[3].clone());
    }

    let widest = bosses.iter().map(|(_, b)| b.len()).max().unwrap_or(0);
    if widest > BOSS_CAP {
        return Err(Error::TooManyBosses(widest));
    }

    let mut out = banner("Every act's shape and its bosses.", "acts.txt", &build);
    writeln!(out, "\nuse super::encounters::Encounter;").unwrap();
    writeln!(out, "use crate::Few;").unwrap();
    writeln!(out, "use serde::{{Deserialize, Serialize}};\n").unwrap();

    emit_shape(&mut out);
    emit_acts(&mut out, &acts, &bosses)?;

    let path = root.join("acts.rs");
    error::write(&path, &out)?;

    println!(
        "  acts: {} ({} a run can visit)",
        acts.len(),
        acts.iter().filter(|r| r[2] != "-1").count()
    );

    Ok(build)
}

/// The most bosses an act reveals.
///
/// Three apiece in this build. A cap rather than a guess. Generation fails
/// rather than truncating if one ever grows, and it is what lets the list be
/// inline instead of a pointer.
const BOSS_CAP: usize = 3;

fn emit_shape(out: &mut String) {
    writeln!(
        out,
        "/// The bosses an act reveals, in discovery order.\n\
         pub type Bosses = Few<Encounter, {BOSS_CAP}>;\n\
         \n\
         /// What is true of an act with no run in progress.\n\
         #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]\n\
         pub struct ActData {{\n\
         \x20   /// Where in a run it falls — and not a unique key.\n\
         \x20   ///\n\
         \x20   /// `OVERGROWTH` and `UNDERDOCKS` are both 0: they are the two\n\
         \x20   /// alternative first acts, and `is_default` is what separates\n\
         \x20   /// them. Signed, because the deprecated act is -1.\n\
         \x20   pub index: i8,\n\
         \x20   /// Whether a run starts here when nothing else chose.\n\
         \x20   pub is_default: bool,\n\
         \x20   /// How many rooms the map is before anything modifies it. They\n\
         \x20   /// shrink across a run: 15, 15, 14, 13.\n\
         \x20   pub rooms: u8,\n\
         \x20   /// How many of the act's first fights come from the weak pool.\n\
         \x20   pub weak_encounters: u8,\n\
         \x20   /// The bosses it reveals, in the order a player meets them\n\
         \x20   /// across runs. Order is the rule: it decides which boss a first\n\
         \x20   /// run ends against.\n\
         \x20   pub bosses: Bosses,\n\
         }}\n"
    )
    .unwrap();
}

fn emit_acts(
    out: &mut String,
    acts: &[&Vec<String>],
    bosses: &[(String, Vec<String>)],
) -> Result<(), Error> {
    writeln!(
        out,
        "/// Every act in the build, in the order a run visits them.\n\
         ///\n\
         /// Five, not the four `ModelDb.Acts` lists: the deprecated one is\n\
         /// reflected in like every other domain's placeholders, and its index\n\
         /// of -1 is what tells it apart.\n\
         ///\n\
         /// The id is the serde rename, and the only place it is spelled."
    )
    .unwrap();
    writeln!(out, "{DERIVES}").unwrap();
    writeln!(out, "#[repr({})]", repr(acts.len())?).unwrap();
    writeln!(out, "pub enum Act {{").unwrap();
    for row in acts {
        writeln!(out, "    #[serde(rename = \"{}\")]", row[1]).unwrap();
        writeln!(out, "    {},", camel(&row[1])).unwrap();
    }
    writeln!(out, "}}\n").unwrap();

    writeln!(out, "impl sts2_core::Table for Act {{").unwrap();
    writeln!(out, "    type Data = ActData;\n").unwrap();
    writeln!(
        out,
        "    /// Every act, so callers can sweep the table without a way to\n\
         \x20   /// enumerate an enum."
    )
    .unwrap();
    writeln!(out, "    const ALL: &'static [Self] = &[").unwrap();
    for row in acts {
        writeln!(out, "        Act::{},", camel(&row[1])).unwrap();
    }
    writeln!(out, "    ];\n").unwrap();

    let mut table: Vec<String> = Vec::new();
    for row in acts {
        let id = &row[1];
        let number = |what: &str, v: &str| DumpError::number::<u8>(format_args!("{id}: {what}"), v);
        let index: i8 = DumpError::number(format_args!("{id}: index"), &row[2])?;

        let list = bosses
            .iter()
            .find(|(act, _)| act == id)
            .map(|(_, b)| {
                b.iter()
                    .map(|e| format!("Encounter::{}", camel(e)))
                    .collect::<Vec<_>>()
                    .join(", ")
            })
            .unwrap_or_default();

        table.push(format!(
            "ActData {{\n\
             \x20       index: {index},\n\
             \x20       is_default: {},\n\
             \x20       rooms: {},\n\
             \x20       weak_encounters: {},\n\
             \x20       bosses: Bosses::new(&[{list}]),\n\
             \x20   }}",
            row[3] == "1",
            number("rooms", &row[4])?,
            number("weak encounters", &row[5])?,
        ));
    }
    writeln!(out, "    /// The act's shape and its bosses.").unwrap();
    writeln!(out, "    fn data(self) -> &'static ActData {{").unwrap();
    writeln!(out, "        &ROWS[self as usize]").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out, "}}\n").unwrap();
    super::rows(out, "ActData", &table);

    // The two room generation deals by, off the same row. A method rather than
    // a reach into `data`, because a caller holding only a `ContentVersion`
    // cannot see what `Table::Data` is.
    writeln!(
        out,
        "impl sts2_core::ActTable for Act {{\n\
         \x20   /// How many rooms an act's map holds.\n\
         \x20   fn rooms(self) -> u8 {{\n\
         \x20       <Self as sts2_core::Table>::data(self).rooms\n\
         \x20   }}\n\
         \n\
         \x20   /// How many of those open the act, dealt from the weak fights.\n\
         \x20   fn weak_encounters(self) -> u8 {{\n\
         \x20       <Self as sts2_core::Table>::data(self).weak_encounters\n\
         \x20   }}\n\
         \n\
         \x20   /// Whether an ordinary run is played through this act.\n\
         \x20   fn played(self) -> bool {{\n\
         \x20       <Self as sts2_core::Table>::data(self).is_default\n\
         \x20   }}\n\
         }}"
    )
    .unwrap();

    Ok(())
}
